def _assign_referral_codes(apps, schema_editor):
    """Doplní unikátny 8-miestny referral_code každému existujúcemu
    používateľovi, ktorý ho ešte nemá (novo pridané pole)."""
    User = apps.get_model('users', 'User')
    alphabet = string.ascii_uppercase + string.digits
    used = set(User.objects.exclude(referral_code='').values_list('referral_code', flat=True))
    for user in User.objects.filter(referral_code=''):
        while True:
            candidate = ''.join(random.choices(alphabet, k=8))
            if candidate not in used:
                used.add(candidate)
                user.referral_code = candidate
                user.save(update_fields=['referral_code'])
                break


